306	# --- clasificacion del codigo de salida de 'podman run' ---
307	#
308	# Convencion de podman/docker: 125 es un fallo del PROPIO podman (no pudo
309	# arrancar el contenedor), 126 comando no ejecutable, 127 comando no
310	# encontrado. Cualquier otro codigo es el que el CONTENEDOR informo, y esa
311	# distincion es la que separa «no pude medir» (error) de «medi, y esto dio»
312	# (efectivo/no-efectivo).
313	_podman_cap_is_podman_level_error() {
314	  local rc="$1"
315	  [[ "$rc" -eq 125 || "$rc" -eq 126 || "$rc" -eq 127 ]]
316	}
