318	# --- capacidad: run ---
319	_podman_cap_measure_run() {
320	  local cname="${_PODMAN_CAP_CONTAINER_PREFIX}-run" out rc
321	  _PODMAN_CAP_CONTAINERS+=("$cname")
322	  out="$("$PODMAN" run --rm --network none --name "$cname" \
323	        "$_PODMAN_CAP_IMAGE" /bin/helper run 2>&1)"
324	  rc=$?
325	  if _podman_cap_is_podman_level_error "$rc"; then
326	    printf 'run\terror\tpodman rc=%s: %s\n' "$rc" "${out:0:200}"
327	  elif [[ "$rc" -eq 0 ]]; then
328	    printf 'run\tefectivo\tel contenedor corrio y salio 0\n'
329	  else
330	    printf 'run\tno-efectivo\tel contenedor corrio y salio %s\n' "$rc"
331	  fi
332	}
