334	# --- capacidad: pids_limit ---
335	_podman_cap_measure_pids_limit() {
336	  local cname="${_PODMAN_CAP_CONTAINER_PREFIX}-pids" out rc created
337	  _PODMAN_CAP_CONTAINERS+=("$cname")
338	  out="$("$PODMAN" run --rm --network none --pids-limit 16 --name "$cname" \
339	        "$_PODMAN_CAP_IMAGE" /bin/helper fork 64 2>"$_PODMAN_CAP_WORK/pids.err")"
340	  rc=$?
341	  if _podman_cap_is_podman_level_error "$rc"; then
342	    printf 'pids_limit\terror\tpodman rc=%s: %s\n' "$rc" \
343	      "$(head -c 200 "$_PODMAN_CAP_WORK/pids.err")"
344	    return
345	  fi
346	  created="$(printf '%s' "$out" | tr -dc '0-9')"
347	  if [[ -z "$created" ]]; then
348	    printf 'pids_limit\terror\tsalida sin conteo legible (rc=%s): %s\n' "$rc" "${out:0:200}"
349	    return
350	  fi
351	  if [[ "$created" -le 16 ]]; then
352	    printf 'pids_limit\tefectivo\tlogro %s/64 procesos con --pids-limit 16\n' "$created"
353	  else
354	    printf 'pids_limit\tno-efectivo\tlogro %s/64 procesos con --pids-limit 16\n' "$created"
355	  fi
356	}
