376	# --- capacidad: cleanup ---
377	#
378	# Lanza el ayudante en modo `sleep` para tener un proceso vivo que limpiar,
379	# retira con `podman rm -f`, y comprueba DOS cosas: que el contenedor ya no
380	# aparece listado (ni con -a) y que ningun proceso del ayudante sobrevive en
381	# el anfitrion. El patron de `pgrep` va con la clase de corchetes en su
382	# primer caracter —nunca desnudo— para no casar consigo mismo (la propia
383	# linea de comando de `pgrep -f` contendria el patron literal).
384	_podman_cap_measure_cleanup() {
385	  local cname="${_PODMAN_CAP_CONTAINER_PREFIX}-cleanup"
386	  local listed proc_line rm_rc start_err
387	  local marker_pattern="[${_PODMAN_CAP_HELPER_MARKER:0:1}]${_PODMAN_CAP_HELPER_MARKER:1}"
388	  _PODMAN_CAP_CONTAINERS+=("$cname")
389	
390	  if ! "$PODMAN" run -d --network none --name "$cname" "$_PODMAN_CAP_IMAGE" \
391	       /bin/helper sleep 30 "$_PODMAN_CAP_HELPER_MARKER" \
392	       >/dev/null 2>"$_PODMAN_CAP_WORK/cleanup-start.err"; then
393	    start_err="$(head -c 200 "$_PODMAN_CAP_WORK/cleanup-start.err")"
394	    printf 'cleanup\terror\tno se pudo lanzar el contenedor a limpiar: %s\n' "$start_err"
395	    return
396	  fi
397	
398	  "$PODMAN" rm -f "$cname" >/dev/null 2>"$_PODMAN_CAP_WORK/cleanup-rm.err"
399	  rm_rc=$?
400	
401	  listed="$("$PODMAN" ps -a --filter "name=^${cname}\$" --format '{{.Names}}' 2>/dev/null)"
402	  proc_line="$(pgrep -f "$marker_pattern" 2>/dev/null || true)"
403	
404	  if [[ "$rm_rc" -ne 0 ]]; then
405	    printf 'cleanup\terror\t%s rm -f fallo: %s\n' "$PODMAN" \
406	      "$(head -c 200 "$_PODMAN_CAP_WORK/cleanup-rm.err")"
407	  elif [[ -n "$listed" || -n "$proc_line" ]]; then
408	    printf 'cleanup\tno-efectivo\tlistado=%s proceso=%s\n' \
409	      "${listed:-ninguno}" "${proc_line:-ninguno}"
410	  else
411	    printf 'cleanup\tefectivo\tsin contenedor listado y sin proceso del ayudante en el anfitrion\n'
412	  fi
413	}
