415	# --- capacidad: network_none ---
416	#
417	# `efectivo` sólo si las dos formas de salir a la red fallan bajo
418	# --network none: TCP/IPv4 a una IP fija (sin pasar por el resolvedor) y una
419	# consulta DNS por UDP (que SI pasa por el resolvedor). Dos contenedores,
420	# porque el ayudante mide un modo por invocacion.
421	_podman_cap_measure_network_none() {
422	  local cname_tcp="${_PODMAN_CAP_CONTAINER_PREFIX}-net-tcp"
423	  local cname_dns="${_PODMAN_CAP_CONTAINER_PREFIX}-net-dns"
424	  local out_tcp out_dns rc_tcp rc_dns tcp_failed=0 dns_failed=0
425	  _PODMAN_CAP_CONTAINERS+=("$cname_tcp")
426	  _PODMAN_CAP_CONTAINERS+=("$cname_dns")
427	
428	  out_tcp="$("$PODMAN" run --rm --network none --name "$cname_tcp" \
429	        "$_PODMAN_CAP_IMAGE" /bin/helper net 2>&1)"
430	  rc_tcp=$?
431	  if _podman_cap_is_podman_level_error "$rc_tcp"; then
432	    printf 'network_none\terror\tpodman rc=%s (tcp): %s\n' "$rc_tcp" "${out_tcp:0:200}"
433	    return
434	  fi
435	
436	  out_dns="$("$PODMAN" run --rm --network none --name "$cname_dns" \
437	        "$_PODMAN_CAP_IMAGE" /bin/helper dns 2>&1)"
438	  rc_dns=$?
439	  if _podman_cap_is_podman_level_error "$rc_dns"; then
440	    printf 'network_none\terror\tpodman rc=%s (dns): %s\n' "$rc_dns" "${out_dns:0:200}"
441	    return
442	  fi
443	
444	  [[ "$out_tcp" == *"net_connect=fail"* ]] && tcp_failed=1
445	  [[ "$out_dns" == *"dns_send=fail"* || "$out_dns" == *"dns_answer=fail"* ]] && dns_failed=1
446	
447	  if [[ "$tcp_failed" -eq 1 && "$dns_failed" -eq 1 ]]; then
448	    printf 'network_none\tefectivo\tTCP y DNS fallan con --network none: %s | %s\n' \
449	      "$out_tcp" "$out_dns"
450	  else
451	    printf 'network_none\tno-efectivo\tTCP=%s DNS=%s con --network none\n' "$out_tcp" "$out_dns"
452	  fi
453	}
