455	# --- capacidad: read_only_rootfs ---
456	#
457	# `--read-only` solo NO cierra /tmp, /run, /var/tmp ni /dev/shm: Podman los
458	# monta como tmpfs, y eso sigue siendo escribible. Por eso esta sonda exige
459	# ademas `--read-only-tmpfs=false`, que cierra tambien esos montajes; medido
460	# en `.claude/workbench/podman-isolation-2b-gaps-20260929T140754/`.
461	# `efectivo` solo si escribir en / Y en /tmp fallan las dos.
462	_podman_cap_measure_read_only_rootfs() {
463	  local cname_root="${_PODMAN_CAP_CONTAINER_PREFIX}-ro-root"
464	  local cname_tmp="${_PODMAN_CAP_CONTAINER_PREFIX}-ro-tmp"
465	  local out_root out_tmp rc_root rc_tmp root_failed=0 tmp_failed=0
466	  _PODMAN_CAP_CONTAINERS+=("$cname_root")
467	  _PODMAN_CAP_CONTAINERS+=("$cname_tmp")
468	
469	  out_root="$("$PODMAN" run --rm --network none --read-only --read-only-tmpfs=false \
470	        --name "$cname_root" "$_PODMAN_CAP_IMAGE" /bin/helper write /probe-write 2>&1)"
471	  rc_root=$?
472	  if _podman_cap_is_podman_level_error "$rc_root"; then
473	    printf 'read_only_rootfs\terror\tpodman rc=%s (/): %s\n' "$rc_root" "${out_root:0:200}"
474	    return
475	  fi
476	
477	  out_tmp="$("$PODMAN" run --rm --network none --read-only --read-only-tmpfs=false \
478	        --name "$cname_tmp" "$_PODMAN_CAP_IMAGE" /bin/helper write /tmp/probe-write 2>&1)"
479	  rc_tmp=$?
480	  if _podman_cap_is_podman_level_error "$rc_tmp"; then
481	    printf 'read_only_rootfs\terror\tpodman rc=%s (/tmp): %s\n' "$rc_tmp" "${out_tmp:0:200}"
482	    return
483	  fi
484	
485	  [[ "$out_root" == *"write=fail"* ]] && root_failed=1
486	  [[ "$out_tmp" == *"write=fail"* ]] && tmp_failed=1
487	
488	  if [[ "$root_failed" -eq 1 && "$tmp_failed" -eq 1 ]]; then
489	    printf 'read_only_rootfs\tefectivo\tescribir en / y /tmp falla con --read-only --read-only-tmpfs=false: %s | %s\n' \
490	      "$out_root" "$out_tmp"
491	  else
492	    printf 'read_only_rootfs\tno-efectivo\t/=%s /tmp=%s con --read-only --read-only-tmpfs=false\n' \
493	      "$out_root" "$out_tmp"
494	  fi
495	}
