497	# --- capacidad: cpu_limit ---
498	#
499	# La medida es sensible a la carga del anfitrion: correr esta sonda junto a
500	# otras que tambien usan CPU puede subir el cociente medido. El umbral
501	# (`_PODMAN_CAP_CPU_LIMIT_THRESHOLD`) deja margen entre el limite pedido
502	# (0.5) y el techo sin limite de 2 hilos (~2.0) para no confundir esa
503	# contencion con que el limite no aplique.
504	_podman_cap_measure_cpu_limit() {
505	  local cname="${_PODMAN_CAP_CONTAINER_PREFIX}-cpu" out rc ratio
506	  _PODMAN_CAP_CONTAINERS+=("$cname")
507	  out="$("$PODMAN" run --rm --network none --cpus 0.5 --name "$cname" \
508	        "$_PODMAN_CAP_IMAGE" /bin/helper cpu "$_PODMAN_CAP_CPU_LIMIT_THREADS" 2>&1)"
509	  rc=$?
510	  if _podman_cap_is_podman_level_error "$rc"; then
511	    printf 'cpu_limit\terror\tpodman rc=%s: %s\n' "$rc" "${out:0:200}"
512	    return
513	  fi
514	  ratio="$(printf '%s' "$out" | grep -o 'cpu_ratio=[0-9.]*' | cut -d= -f2)"
515	  if [[ -z "$ratio" ]]; then
516	    printf 'cpu_limit\terror\tsalida sin cpu_ratio legible (rc=%s): %s\n' "$rc" "${out:0:200}"
517	    return
518	  fi
519	  if awk -v r="$ratio" -v t="$_PODMAN_CAP_CPU_LIMIT_THRESHOLD" 'BEGIN { exit !(r < t) }'; then
520	    printf 'cpu_limit\tefectivo\t%s nucleos obtenidos con --cpus 0.5 y %s hilos (< %s)\n' \
521	      "$ratio" "$_PODMAN_CAP_CPU_LIMIT_THREADS" "$_PODMAN_CAP_CPU_LIMIT_THRESHOLD"
522	  else
523	    printf 'cpu_limit\tno-efectivo\t%s nucleos obtenidos con --cpus 0.5 y %s hilos (>= %s)\n' \
524	      "$ratio" "$_PODMAN_CAP_CPU_LIMIT_THREADS" "$_PODMAN_CAP_CPU_LIMIT_THRESHOLD"
525	  fi
526	}
