528	# --- capacidad: readonly_mount ---
529	#
530	# Monta un directorio DESECHABLE PROPIO —subdirectorio de
531	# `_PODMAN_CAP_WORK`, que el trap ya retira— nunca el repo. `efectivo` solo
532	# si leer el archivo sembrado funciona Y escribir uno nuevo falla las dos.
533	_podman_cap_measure_readonly_mount() {
534	  local cname_read="${_PODMAN_CAP_CONTAINER_PREFIX}-ro-mount-read"
535	  local cname_write="${_PODMAN_CAP_CONTAINER_PREFIX}-ro-mount-write"
536	  local mountdir="$_PODMAN_CAP_WORK/readonly-mount"
537	  local out_read out_write rc_read rc_write read_ok=0 write_failed=0
538	  _PODMAN_CAP_CONTAINERS+=("$cname_read")
539	  _PODMAN_CAP_CONTAINERS+=("$cname_write")
540	
541	  mkdir -p "$mountdir"
542	  printf 'seed\n' > "$mountdir/seed.txt"
543	
544	  out_read="$("$PODMAN" run --rm --network none -v "$mountdir:/mnt/ro:ro" \
545	        --name "$cname_read" "$_PODMAN_CAP_IMAGE" /bin/helper read /mnt/ro/seed.txt 2>&1)"
546	  rc_read=$?
547	  if _podman_cap_is_podman_level_error "$rc_read"; then
548	    printf 'readonly_mount\terror\tpodman rc=%s (read): %s\n' "$rc_read" "${out_read:0:200}"
549	    return
550	  fi
551	
552	  out_write="$("$PODMAN" run --rm --network none -v "$mountdir:/mnt/ro:ro" \
553	        --name "$cname_write" "$_PODMAN_CAP_IMAGE" /bin/helper write /mnt/ro/probe-write 2>&1)"
554	  rc_write=$?
555	  if _podman_cap_is_podman_level_error "$rc_write"; then
556	    printf 'readonly_mount\terror\tpodman rc=%s (write): %s\n' "$rc_write" "${out_write:0:200}"
557	    return
558	  fi
559	
560	  [[ "$out_read" == *"read=ok"* ]] && read_ok=1
561	  [[ "$out_write" == *"write=fail"* ]] && write_failed=1
562	
563	  if [[ "$read_ok" -eq 1 && "$write_failed" -eq 1 ]]; then
564	    printf 'readonly_mount\tefectivo\tmontaje :ro permite leer y rehusa escribir: %s | %s\n' \
565	      "$out_read" "$out_write"
566	  else
567	    printf 'readonly_mount\tno-efectivo\tread=%s write=%s con montaje :ro\n' "$out_read" "$out_write"
568	  fi
569	}
